function split(s){return s.split('|')} function el(s){return document.querySelector(s)} function put(e,v,html=false){if(e){html?e.innerHTML=v:e.textContent=v}} function title(s){let i=s.indexOf('. ');return i<0?s:s.slice(0,i+1)+'<br><em>'+s.slice(i+2)+'</em>'}
function links(lang){document.querySelectorAll('header nav a,main a[href^="."]').forEach(a=>{const u=new URL(a.href,location.href);if(u.origin!==location.origin)return;lang==='en'?u.searchParams.delete('lang'):u.searchParams.set('lang',lang);a.href=u.pathname+u.search+u.hash})}
